changeSet.sql:
ALTER TABLE clinlims.eqa_result DROP CONSTRAINT uk_eqa_result_dist_org_test;

CREATE UNIQUE INDEX uk_eqa_result_dist_org_test
ON clinlims.eqa_result (eqa_distribution_id, participant_organization_id, test_id)
WHERE eqa_panel_sample_id IS NULL;

CREATE UNIQUE INDEX uk_eqa_result_dist_org_sample
ON clinlims.eqa_result (eqa_distribution_id, participant_organization_id, eqa_panel_sample_id)
WHERE eqa_panel_sample_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS clinlims.uk_eqa_result_dist_org_sample;
DROP INDEX IF EXISTS clinlims.uk_eqa_result_dist_org_test;

ALTER TABLE clinlims.eqa_result
ADD CONSTRAINT uk_eqa_result_dist_org_test
UNIQUE (eqa_distribution_id, participant_organization_id, test_id);
